"""Acoustic polish after island/PCM pack (Transub Pro ten_pcm chain).

Order: waveform snap → silent-body shift → onset delay → hold extend → end clamp.
Operates on engine cue dicts (``start``/``end`` seconds) + float32 mono @ 16 kHz.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Any

import numpy as np

_SAMPLE_RATE = 16000


def _char_len(text: str) -> int:
    return len(re.sub(r"[\s　]+", "", text or ""))


def _sorted_cues(cues: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return sorted(
        (dict(c) for c in cues if isinstance(c, dict)),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )


def _rms_envelope(pcm: np.ndarray, *, hop_ms: float = 20.0) -> tuple[np.ndarray, float]:
    sr = _SAMPLE_RATE
    hop = max(1, int(round(hop_ms * sr / 1000.0)))
    n = int(pcm.size // hop)
    if n < 2:
        return np.zeros(0, dtype=np.float32), hop_ms
    frames = pcm[: n * hop].reshape(n, hop).astype(np.float32)
    rms = np.sqrt(np.mean(np.square(frames), axis=1) + 1e-12)
    return rms.astype(np.float32), float(hop_ms)


def _slice_window(
    pcm: np.ndarray,
    start_ms: int,
    end_ms: int,
    *,
    pre_ms: int,
    post_ms: int,
) -> tuple[np.ndarray, int]:
    win_start = max(0, start_ms - pre_ms)
    win_end = end_ms + post_ms
    i0 = int(round(win_start * _SAMPLE_RATE / 1000.0))
    i1 = int(round(win_end * _SAMPLE_RATE / 1000.0))
    i0 = max(0, min(int(pcm.size), i0))
    i1 = max(i0 + 1, min(int(pcm.size), i1))
    return pcm[i0:i1].copy(), win_start


def _chunk_rms(samples: np.ndarray, a: int, b: int) -> float:
    a = max(0, a)
    b = min(int(samples.size), b)
    if b <= a:
        return 0.0
    chunk = samples[a:b].astype(np.float32)
    return float(np.sqrt(np.mean(np.square(chunk)) + 1e-12))


def _frame_rms(samples: np.ndarray, hop: int) -> list[tuple[int, float]]:
    out: list[tuple[int, float]] = []
    n = int(samples.size)
    for i in range(0, n - hop + 1, hop):
        out.append((i, _chunk_rms(samples, i, i + hop)))
    return out


def _median(vals: list[float]) -> float:
    if not vals:
        return 0.0
    s = sorted(vals)
    return s[len(s) // 2]


@dataclass(frozen=True)
class WaveformSnapParams:
    pre_ms: int = 600
    post_ms: int = 600
    head_pad_ms: int = 40
    tail_pad_ms: int = 220
    min_dur_ms: int = 320
    min_shift_ms: int = 45
    max_shift_ms: int = 1200
    silence_thr_factor: float = 0.32
    spill_thr: float = 0.75
    gap_ms: int = 1


def snap_cues_to_waveform(
    cues: list[dict[str, Any]],
    pcm: np.ndarray,
    *,
    params: WaveformSnapParams | None = None,
) -> tuple[list[dict[str, Any]], str]:
    """Conservative edge snap from energy spill / valleys (Pro port)."""
    p = params or WaveformSnapParams()
    ordered = _sorted_cues(cues)
    if not ordered or pcm is None or pcm.size < 16:
        return ordered, "empty"

    proposed: list[tuple[int, int, int, bool]] = []
    changed_n = 0
    for i, cue in enumerate(ordered):
        cue_start = int(round(float(cue.get("start") or 0) * 1000))
        cue_end = max(cue_start + 1, int(round(float(cue.get("end") or 0) * 1000)))
        win, win_start = _slice_window(
            pcm, cue_start, cue_end, pre_ms=p.pre_ms, post_ms=p.post_ms
        )
        dur_ms = max(1, cue_end - cue_start)
        pre_n = int(round(p.pre_ms * _SAMPLE_RATE / 1000.0))
        body_n = int(round(dur_ms * _SAMPLE_RATE / 1000.0))
        body_start = min(int(win.size), pre_n)
        body_end = min(int(win.size), pre_n + body_n)
        post_start = body_end
        rms_body = _chunk_rms(win, body_start, body_end)
        rms_pre = _chunk_rms(win, 0, body_start)
        rms_post = _chunk_rms(win, post_start, int(win.size))
        edge_pre = _chunk_rms(
            win, max(0, body_start - int(round(0.15 * _SAMPLE_RATE))), body_start
        )
        edge_post = _chunk_rms(
            win, body_end, min(int(win.size), body_end + int(round(0.15 * _SAMPLE_RATE)))
        )
        hop = max(1, int(round(0.02 * _SAMPLE_RATE)))
        series = _frame_rms(win, hop)
        body_frames = [(j, r) for j, r in series if body_start <= j < body_end]
        body_med = _median([r for _, r in body_frames])
        silence_thr = max(0.01, body_med * 0.35)
        near_start = body_frames[: min(8, len(body_frames))]
        near_end = body_frames[max(0, len(body_frames) - 8) :]
        start_valley = min((r for _, r in near_start), default=0.0)
        end_valley = min((r for _, r in near_end), default=0.0)
        spill_start = edge_pre / rms_body if rms_body > 1e-6 else 99.0
        spill_end = edge_post / rms_body if rms_body > 1e-6 else 99.0
        ratio_pre = rms_pre / rms_body if rms_body > 1e-6 else 99.0
        ratio_post = rms_post / rms_body if rms_body > 1e-6 else 99.0
        reasons: list[str] = []
        chars = _char_len(str(cue.get("text") or ""))
        if rms_body < 0.012 and chars >= 3:
            reasons.append("body_quiet")
        if spill_start > 0.85 and ratio_pre > 0.7:
            reasons.append("start_spill")
        if spill_end > 0.85 and ratio_post > 0.7:
            reasons.append("end_spill")
        if start_valley > silence_thr * 1.8 and spill_start > 0.6:
            reasons.append("start_not_in_valley")
        if end_valley > silence_thr * 1.8 and spill_end > 0.6:
            reasons.append("end_not_in_valley")
        want_start = (
            "start_spill" in reasons
            or "start_not_in_valley" in reasons
            or spill_start > p.spill_thr
        )
        want_end = (
            "end_spill" in reasons
            or "end_not_in_valley" in reasons
            or spill_end > p.spill_thr
        )
        if not want_start and not want_end:
            proposed.append((i, cue_start, cue_end, False))
            continue

        thr = max(0.012, body_med * p.silence_thr_factor)
        first = -1
        last = -1
        for j, r in series:
            if r >= thr:
                if first < 0:
                    first = j
                last = j
        if first < 0 or last < first:
            proposed.append((i, cue_start, cue_end, False))
            continue
        speech_start = win_start + int(round(first * 1000.0 / _SAMPLE_RATE))
        speech_end = win_start + int(round((last + hop) * 1000.0 / _SAMPLE_RATE))
        new_start = cue_start
        new_end = cue_end
        if want_start:
            cand = speech_start - p.head_pad_ms
            if cand < cue_start:
                new_start = cand
        if want_end:
            cand = speech_end + p.tail_pad_ms
            if cand > cue_end:
                new_end = cand
        window_lo = cue_start - p.pre_ms
        window_hi = cue_end + p.post_ms
        prev_limit = (
            int(round(float(ordered[i - 1].get("end") or 0) * 1000)) + p.gap_ms
            if i > 0
            else window_lo
        )
        next_limit = (
            int(round(float(ordered[i + 1].get("start") or 0) * 1000)) - p.gap_ms
            if i + 1 < len(ordered)
            else window_hi
        )
        new_start = max(window_lo, prev_limit, int(round(new_start)))
        new_end = min(window_hi, next_limit, int(round(new_end)))
        new_start = min(new_start, cue_start)
        new_end = max(new_end, cue_end)
        if cue_start - new_start > p.max_shift_ms:
            new_start = cue_start - p.max_shift_ms
        if new_end - cue_end > p.max_shift_ms:
            new_end = cue_end + p.max_shift_ms
        if new_end - new_start < p.min_dur_ms:
            proposed.append((i, cue_start, cue_end, False))
            continue
        if (
            abs(new_start - cue_start) < p.min_shift_ms
            and abs(new_end - cue_end) < p.min_shift_ms
        ):
            proposed.append((i, cue_start, cue_end, False))
            continue
        proposed.append((i, new_start, new_end, True))
        changed_n += 1

    out: list[dict[str, Any]] = []
    for i, cue in enumerate(ordered):
        _idx, start_ms, end_ms, did = proposed[i]
        if out and start_ms < int(round(float(out[-1].get("end") or 0) * 1000)) + p.gap_ms:
            start_ms = int(round(float(out[-1].get("end") or 0) * 1000)) + p.gap_ms
        if i + 1 < len(ordered):
            nxt = proposed[i + 1][1]
            end_ms = min(end_ms, nxt - p.gap_ms)
        if end_ms - start_ms < 120:
            start_ms = int(round(float(cue.get("start") or 0) * 1000))
            end_ms = int(round(float(cue.get("end") or 0) * 1000))
            did = False
        item = dict(cue)
        if did or (start_ms, end_ms) != (
            int(round(float(cue.get("start") or 0) * 1000)),
            int(round(float(cue.get("end") or 0) * 1000)),
        ):
            item["start"] = round(start_ms / 1000.0, 3)
            item["end"] = round(max(start_ms + 120, end_ms) / 1000.0, 3)
        out.append(item)
    return out, f"snapped={changed_n}/{len(ordered)}"


def shift_silent_cues_forward(
    cues: list[dict[str, Any]],
    pcm: np.ndarray,
    *,
    silence_ratio: float = 0.12,
    max_forward_ms: int = 20000,
    min_shift_ms: int = 200,
    gap_ms: int = 40,
    only_before_ms: int = 60000,
    max_shifts: int = 3,
) -> tuple[list[dict[str, Any]], str]:
    ordered = _sorted_cues(cues)
    rms, hop_ms = _rms_envelope(pcm)
    if not ordered or rms.size < 4:
        return ordered, "no_env"
    out: list[dict[str, Any]] = []
    shifted = 0
    for i, cue in enumerate(ordered):
        start = int(round(float(cue.get("start") or 0) * 1000))
        end = max(start + 80, int(round(float(cue.get("end") or 0) * 1000)))
        dur = end - start
        if start >= only_before_ms or shifted >= max_shifts:
            out.append(cue)
            continue
        i0 = max(0, min(rms.size - 1, int(start / hop_ms)))
        i1 = max(i0 + 1, min(rms.size - 1, int(end / hop_ms)))
        body = float(rms[i0 : i1 + 1].mean())
        fwd_end = min(int(rms.size * hop_ms), end + max_forward_ms)
        j1 = max(i1, min(rms.size - 1, int(fwd_end / hop_ms)))
        peak = float(rms[i0 : j1 + 1].max()) if j1 > i0 else body
        if peak < 1e-6 or body >= peak * silence_ratio:
            out.append(cue)
            continue
        thr = max(peak * max(silence_ratio, 0.08), 1e-4)
        search_from = i1 + max(1, int(80 / hop_ms))
        onset_i = None
        run = 0
        need = max(3, int(100 / hop_ms))
        for idx in range(search_from, j1 + 1):
            if float(rms[idx]) >= thr:
                run += 1
                if run >= need:
                    onset_i = idx - need + 1
                    break
            else:
                run = 0
        if onset_i is None:
            out.append(cue)
            continue
        new_start = int(round(onset_i * hop_ms))
        delta = new_start - start
        if delta < min_shift_ms:
            out.append(cue)
            continue
        new_end = new_start + dur
        if i + 1 < len(ordered):
            limit = int(round(float(ordered[i + 1].get("start") or 0) * 1000)) - gap_ms
            if new_end > limit:
                out.append(cue)
                continue
        if out and new_start < int(round(float(out[-1].get("end") or 0) * 1000)) + gap_ms:
            out.append(cue)
            continue
        shifted += 1
        item = dict(cue)
        item["start"] = round(new_start / 1000.0, 3)
        item["end"] = round(new_end / 1000.0, 3)
        out.append(item)
    return out, f"shifted={shifted}/{len(ordered)}"


def delay_cues_to_onset(
    cues: list[dict[str, Any]],
    pcm: np.ndarray,
    *,
    search_ms: int = 700,
    threshold_ratio: float = 0.08,
    quiet_ratio: float = 0.35,
    gap_ms: int = 20,
) -> tuple[list[dict[str, Any]], str]:
    ordered = _sorted_cues(cues)
    rms, hop_ms = _rms_envelope(pcm)
    if not ordered or rms.size < 4:
        return ordered, "no_env"
    out: list[dict[str, Any]] = []
    delayed = 0
    for i, cue in enumerate(ordered):
        start = int(round(float(cue.get("start") or 0) * 1000))
        end = max(start + 120, int(round(float(cue.get("end") or 0) * 1000)))
        dur = end - start
        i0 = max(0, min(rms.size - 1, int(start / hop_ms)))
        i1 = max(0, min(rms.size - 1, int((start + search_ms) / hop_ms)))
        window = rms[i0 : i1 + 1]
        if window.size < 3:
            out.append(cue)
            continue
        peak = float(window.max())
        if peak < 1e-6:
            out.append(cue)
            continue
        thr = peak * threshold_ratio
        head_n = max(1, int(120 / hop_ms))
        head = float(window[:head_n].mean())
        if head > peak * quiet_ratio:
            out.append(cue)
            continue
        onset_off = None
        for off, level in enumerate(window.tolist()):
            if level >= thr:
                onset_off = off
                break
        if onset_off is None or onset_off * hop_ms < 80:
            out.append(cue)
            continue
        new_start = start + int(round(onset_off * hop_ms))
        new_end = new_start + dur
        if i + 1 < len(ordered):
            new_end = min(
                new_end,
                int(round(float(ordered[i + 1].get("start") or 0) * 1000)) - gap_ms,
            )
        if out:
            new_start = max(
                new_start,
                int(round(float(out[-1].get("end") or 0) * 1000)) + gap_ms,
            )
        if new_end - new_start < 120:
            out.append(cue)
            continue
        if new_start > start + 40:
            delayed += 1
            item = dict(cue)
            item["start"] = round(new_start / 1000.0, 3)
            item["end"] = round(new_end / 1000.0, 3)
            out.append(item)
        else:
            out.append(cue)
    return out, f"delayed={delayed}/{len(ordered)}"


def extend_cue_holds(
    cues: list[dict[str, Any]],
    *,
    min_cps: float = 4.5,
    pad_ms: int = 80,
    gap_ms: int = 40,
    media_end_s: float | None = None,
) -> tuple[list[dict[str, Any]], str]:
    ordered = _sorted_cues(cues)
    if not ordered:
        return ordered, "empty"
    out: list[dict[str, Any]] = []
    extended = 0
    media_end_ms = (
        int(round(float(media_end_s) * 1000)) if media_end_s is not None else None
    )
    for i, cue in enumerate(ordered):
        start = int(round(float(cue.get("start") or 0) * 1000))
        end = max(start + 120, int(round(float(cue.get("end") or 0) * 1000)))
        n = max(_char_len(str(cue.get("text") or "")), 1)
        need = max(320, int(n / max(min_cps, 0.5) * 1000) + pad_ms)
        target = start + need
        if i + 1 < len(ordered):
            limit = int(round(float(ordered[i + 1].get("start") or 0) * 1000)) - gap_ms
        elif media_end_ms is not None:
            limit = media_end_ms
        else:
            limit = max(end, target)
        new_end = min(max(end, target), limit)
        item = dict(cue)
        if new_end > end + 30:
            extended += 1
            item["end"] = round(max(start + 120, new_end) / 1000.0, 3)
        out.append(item)
    return out, f"extended={extended}/{len(ordered)}"


def clamp_cue_ends(
    cues: list[dict[str, Any]],
    pcm: np.ndarray | None = None,
    *,
    min_cps: float = 2.6,
    pad_ms: int = 200,
    gap_ms: int = 40,
    min_dur_ms: int = 1000,
) -> tuple[list[dict[str, Any]], str]:
    """CPS soft ceiling + optional silent-tail trim (starts unchanged)."""
    ordered = _sorted_cues(cues)
    if not ordered:
        return ordered, "empty"
    rms, hop_ms = _rms_envelope(pcm) if pcm is not None and pcm.size else (np.zeros(0), 20.0)
    out: list[dict[str, Any]] = []
    trimmed = 0
    for i, cue in enumerate(ordered):
        start = int(round(float(cue.get("start") or 0) * 1000))
        end = max(start + 120, int(round(float(cue.get("end") or 0) * 1000)))
        raw = str(cue.get("text") or "").lstrip()
        if raw.startswith(("字幕由", "http", "www.")):
            out.append(cue)
            continue
        n = max(_char_len(raw), 1)
        if n <= 3:
            cap = max(min_dur_ms, 1500)
        elif n <= 5:
            cap = max(min_dur_ms, 1800, int(n / max(min_cps, 0.5) * 1000) + pad_ms)
        else:
            cap = max(min_dur_ms, int(n / max(min_cps, 0.5) * 1000) + pad_ms)
        new_end = min(end, start + cap)
        if i + 1 < len(ordered):
            new_end = min(
                new_end,
                int(round(float(ordered[i + 1].get("start") or 0) * 1000)) - gap_ms,
            )
        # Trim trailing silence when energy dies well before end.
        if rms.size >= 4 and new_end - start > 400:
            i0 = max(0, min(rms.size - 1, int(start / hop_ms)))
            i1 = max(i0 + 1, min(rms.size - 1, int(new_end / hop_ms)))
            body = rms[i0 : i1 + 1]
            if body.size >= 4:
                peak = float(body.max())
                thr = max(peak * 0.08, 1e-4)
                last_loud = None
                for off in range(body.size - 1, -1, -1):
                    if float(body[off]) >= thr:
                        last_loud = off
                        break
                if last_loud is not None:
                    tail_ms = int(round((i0 + last_loud + 1) * hop_ms)) + 120
                    if start + 200 <= tail_ms < new_end - 80:
                        new_end = min(new_end, tail_ms)
        new_end = max(start + 120, new_end)
        item = dict(cue)
        if new_end < end - 30:
            trimmed += 1
            item["end"] = round(new_end / 1000.0, 3)
        out.append(item)
    return out, f"trimmed={trimmed}/{len(ordered)}"


__all__ = [
    "WaveformSnapParams",
    "clamp_cue_ends",
    "delay_cues_to_onset",
    "extend_cue_holds",
    "shift_silent_cues_forward",
    "snap_cues_to_waveform",
]
